package cn.adc.shared.config;
import cn.adc.shared.security.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ConfigurationReadinessTest {
 @Test void missingClinicDoesNotInventDataOrDisableIndependentHeadquartersPermission(){var auth=new StaffAuthorization(()->Optional.of("synthetic-hq"),()->Map.of("synthetic-hq",new StaffAuthorization.Grant("v1",Set.of("HQ"),Set.of("DURATION_PUBLISH"),Set.of(),true)));var r=new ConfigurationReadiness(id->{throw new ConfigurationUnavailable();},(id,clinic)->{throw new ConfigurationUnavailable();},auth);assertFalse(r.clinicCapability(1,7,"UC21").ready());assertTrue(r.headquartersPublication().ready());}
 @Test void verifiedInputsAndScopeNeededIndependently(){var clinic=new ClinicConfigurationAdapter(ClinicDirectoryProviderTest.reader(),()->List.of(new ClinicConfigurationAdapter.Entry(1,"SYNTHETIC-clinic","UTC",ClinicDirectoryProviderTest.stamp())));var dentist=new DentistConfigurationAdapter(ClinicDirectoryProviderTest.reader(),()->List.of(new DentistConfigurationAdapter.Entry(7,Set.of(1L),"SYNTHETIC-proof",true,ClinicDirectoryProviderTest.stamp())));var auth=new StaffAuthorization(()->Optional.of("synthetic-manager"),()->Map.of("synthetic-manager",new StaffAuthorization.Grant("v1",Set.of("CLINIC_MANAGER"),Set.of("UC21"),Set.of(1L),false)));var r=new ConfigurationReadiness(clinic,dentist,auth);assertTrue(r.clinicCapability(1,7,"UC21").ready());assertFalse(r.clinicCapability(2,7,"UC21").ready());assertFalse(r.headquartersPublication().ready());}
}
